C = ("observar", "conversar", "actuar")

def main():
    doc = json.loads(F.read_text(encoding="utf-8"))
    need = [t["id"] for t in doc["tips"] if not (set(t["edad"]) & {"6-8", "9-11"})]
    miss = sorted(set(need) - set(P)); extra = sorted(set(P) - set(need))
    if miss or extra: sys.exit(f"Faltan pasos: {miss} · sobran: {extra}")
    for t in doc["tips"]:
        if t["id"] in P:
            es, en = P[t["id"]]
            t["pasos"] = {k: {"es": a, "en": b} for k, a, b in zip(K, es, en)}
    F.write_text(json.dumps(doc, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
    themes = {i["theme"] for i in json.loads((R/"data/items.json").read_text(encoding="utf-8")) if i["kind"] == "alerta"}
    if themes - set(OCA): sys.exit(f"Temas de alerta sin guía: {sorted(themes - set(OCA))}")
    out = {"_nota": "E5.4: guía observar–conversar–actuar por tema de alerta. Generado por tools/e5_pasos_1218.py.",
           "temas": {th: {ctx: {c: {"es": es[k], "en": en[k]} for k, c in enumerate(C)} for ctx, (es, en) in v.items()} for th, v in OCA.items()}}
    (R/"data/alertas_oca.json").write_text(json.dumps(out, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
    print(f"pasos añadidos a {len(P)} tips (12–14 y 15–18) · guía O–C–A para {len(OCA)} temas")

if __name__ == "__main__":
    main()
